+      // Fixed offset bits contribute the same packing cost to every choice.
+      auto cost =
+          std::make_tuple(triton::gpu::bankConflicts(phase, phase, smem).first,
+                          -wordBits, -orderedBits);
+      if (cost < bestCost) {
