+        best = std::move(selected);
+      }
+    }
+  }
+  SmallVector<size_t> order;
+  for (auto reg : best)
+    order.push_back(numOffsetRegBits + reg);
+  for (unsigned i = 0; i < numRegBits; ++i)
+    if (!llvm::is_contained(order, i))
